/** Projected inputs can be absent while STM/projector are starting. */
export function ensureLogFilesExist() {}

function resolveDirValue(value: unknown, label: string) {
  const dirName = String(value ?? "").trim();
  if (!dirName) throw new Error(`missing ${label} directory`);
  return dirName;
}
function resolveDirPath(baseDir: string, dirValue: string) { return path.isAbsolute(dirValue) ? dirValue : path.resolve(baseDir, dirValue); }
function dashboardLayoutEditMode(value: unknown, legacyPushOnEdit: boolean) {
  const selected = value === undefined || value === null || String(value).trim() === "" ? (legacyPushOnEdit ? 3 : 0) : value;
  const mode = Number(selected);
  return Number.isInteger(mode) && mode >= 0 && mode <= 3 ? mode : 0;
}

function streamsErrorCountMode(value: unknown) {
  return Number(value) === 0 ? 0 : 1;
}

function streamsRecentAlertRetentionMin(value: unknown) {
  const minutes = Number(value ?? 30);
  return Number.isInteger(minutes) && minutes >= 0 && minutes <= 1440 ? minutes : 30;
}

function streamsSparklineSamples(value: unknown) {
  const samples = Number(value ?? 60);
  return Number.isInteger(samples) && samples >= 10 && samples <= 600 ? samples : 60;
}

function tooltipDelayMs(value: unknown) {
  const delay = Number(value ?? 250);
  return Number.isInteger(delay) && delay >= 0 && delay <= 1000 ? delay : 250;
}

function optionalFilePath(value: unknown) {
  const file = String(value ?? "").trim();
  return file ? path.resolve(rootDir, file) : undefined;
}
function optionalSocketPath(value: unknown) {
  const socket = String(value ?? "").trim();
  return socket ? path.resolve(socket) : undefined;
}
function resolveFilePath(baseDir: string, value: unknown, label: string) {
  const file = String(value ?? "").trim();
  if (!file) throw new Error(`missing ${label} file`);
  return path.isAbsolute(file) ? file : path.resolve(baseDir, file);
}
function resolveRootDir() {
  const cwd = process.cwd();
  if (path.basename(cwd) === "server" && existsSync(path.join(cwd, "package.json"))) return path.resolve(cwd, "..");
  if (existsSync(path.join(cwd, "client", "package.json")) && existsSync(path.join(cwd, "server", "package.json"))) return cwd;
  if (existsSync(path.join(cwd, "fe", "client", "package.json")) && existsSync(path.join(cwd, "fe", "server", "package.json"))) return path.join(cwd, "fe");
  if (existsSync(path.join(cwd, "server", "package.json"))) return cwd;
  return path.resolve(cwd, "..");
}
function parseArgs(args: string[]) {
  const parsed: Record<string, string> = {};
  const aliases: Record<string, string> = {
    "log-dir": "logDir", "derived-dir": "derivedDir", "event-journal-dir": "eventJournalDir", "stream-state-dir": "streamStateDir",
    "timeline-live-file": "timelineLiveFile", "timeline-events-dir": "timelineEventsDir", "timeline-checkpoint-dir": "timelineCheckpointDir", "timeline-availability-dir": "timelineAvailabilityDir",
    "metrics-samples-1s-dir": "metricsSamples1sDir", "metrics-samples-1m-dir": "metricsSamples1mDir",
    "topology-live-file": "topologyLiveFile", "topology-checkpoint-dir": "topologyCheckpointDir", "topology-updates-dir": "topologyUpdatesDir", "topology-stale-retention-sec": "topologyStaleRetentionSec", "topology-max-stale-edges": "topologyMaxStaleEdges", "topology-max-detail-flows-per-relation": "topologyMaxDetailFlowsPerRelation", "capture-health-live-file": "captureHealthLiveFile", "capture-health-events-file": "captureHealthEventsFile", "capture-health-stale-after-sec": "captureHealthStaleAfterSec",
    "host": "host", "port": "port", "state-dir": "stateDir", "max-events": "maxEvents", "max-timeline-rows": "maxTimelineRows", "streams-patch-interval-ms": "streamsPatchIntervalMs",
    "ws-max-buffered-bytes": "wsMaxBufferedBytes", "stm-config-file": "stmConfigFile", "capture-policy-file": "capturePolicyFile", "process-control-socket": "processControlSocket", "external-pages-dir": "externalPagesDir", "locales-dir": "localesDir", "http-access-log": "httpAccessLog", "metrics-chunk-log": "metricsChunkLog", "events-query-debug-log": "eventsQueryDebugLog", "diagnostic-log": "diagnosticLog"
  };
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (!arg.startsWith("--")) continue;
