import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import type { SetupDraft } from "./setupSettings";

export type SetupProfile = { id: string; name: string; createdAt: number; updatedAt: number; draft: Omit<SetupDraft, "revision"> };
export class SetupProfileError extends Error {}

export class SetupProfiles {
  constructor(private readonly file: string) {}
  async list() { return (await this.read()).profiles; }
  async get(id: string) { const profile = (await this.list()).find((item) => item.id === id); if (!profile) throw new SetupProfileError("configuration profile not found"); return profile; }
  async save(input: { id?: unknown; name?: unknown; draft?: unknown }): Promise<SetupProfile> {
    if (typeof input.name !== "string" || !input.name.trim() || input.name.trim().length > 128) throw new SetupProfileError("profile name must be 1-128 characters");
    if (!input.draft || typeof input.draft !== "object" || Array.isArray(input.draft)) throw new SetupProfileError("profile draft is required");
    const state = await this.read(); const now = Date.now(); const id = typeof input.id === "string" && input.id ? input.id : randomUUID();
    const existing = state.profiles.find((item) => item.id === id);
    const profile: SetupProfile = { id, name: input.name.trim(), createdAt: existing?.createdAt ?? now, updatedAt: now, draft: stripRevision(input.draft as SetupDraft) };
    const profiles = [...state.profiles.filter((item) => item.id !== id), profile].sort((a, b) => a.name.localeCompare(b.name));
    await this.write({ schemaVersion: 1, profiles }); return profile;
  }
  async remove(id: string) { const state = await this.read(); if (!state.profiles.some((item) => item.id === id)) throw new SetupProfileError("configuration profile not found"); await this.write({ schemaVersion: 1, profiles: state.profiles.filter((item) => item.id !== id) }); }
  private async read(): Promise<{ schemaVersion: 1; profiles: SetupProfile[] }> { try { const raw = JSON.parse(await readFile(this.file, "utf8")) as unknown; if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new Error(); const record = raw as Record<string, unknown>; if (record.schemaVersion !== 1 || !Array.isArray(record.profiles)) throw new Error(); return { schemaVersion: 1, profiles: record.profiles.filter(validProfile) as SetupProfile[] }; } catch (error: unknown) { if ((error as NodeJS.ErrnoException).code === "ENOENT") return { schemaVersion: 1, profiles: [] }; throw new SetupProfileError("invalid configuration profiles file"); } }
  private async write(value: unknown) { await mkdir(path.dirname(this.file), { recursive: true }); const temp = path.join(path.dirname(this.file), "." + path.basename(this.file) + "." + process.pid + ".tmp"); await writeFile(temp, JSON.stringify(value, null, 2) + "\n", "utf8"); await rename(temp, this.file); }
}
