    const current = await this.get();
    if (typeof input.revision !== "string" || input.revision !== current.revision) {
      throw new AlertsConflictError("alerts config changed on the server; reload before applying");
    }
    const document = validateDocument(input.document, current.metrics, current.protocols);
    const configured = await this.readConfiguredAlerts();
    await atomicWrite(configured.alertsFile, JSON.stringify(document, null, 2) + "\n");
    return this.get();
  }

  private async readConfiguredAlerts() {
    const stmConfigText = await readFile(this.stmConfigFile, "utf8");
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs)
      ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.alerts ?? configs?.alert_config;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) {
      throw new AlertsValidationError("configs.alerts must be a non-empty relative path");
    }
    const relativePath = validateRelativePath(configuredPath);
    const alertsFile = path.resolve(path.dirname(this.stmConfigFile), relativePath);
    const alertsText = await readFile(alertsFile, "utf8");
    return { stmConfigText, relativePath, alertsFile, alertsText };
  }

  private async readMonitoringTargets(stmConfigText: string): Promise<{ targets: MonitoringTargetDefinition[]; sourceText: string }> {
    const stmConfig = parseObject(stmConfigText, "STM config");
    const configs = stmConfig.configs && typeof stmConfig.configs === "object" && !Array.isArray(stmConfig.configs) ? stmConfig.configs as Record<string, unknown> : undefined;
    const configuredPath = configs?.protocol_map;
    if (typeof configuredPath !== "string" || !configuredPath.trim()) return { targets: [], sourceText: "" };
    const sourceText = await readFile(path.resolve(path.dirname(this.stmConfigFile), validateRelativePath(configuredPath)), "utf8");
    const map = parseObject(sourceText, "protocol map");
    const protocols = Array.isArray(map.protocols) ? map.protocols : [];
    const targets = protocols.flatMap((item): MonitoringTargetDefinition[] => {
      if (!item || typeof item !== "object" || Array.isArray(item)) return [];
      const rule = item as Record<string, unknown>;
      if (typeof rule.id !== "string" || !rule.id.trim() || typeof rule.proto !== "string") return [];
      return [{ id: rule.id, proto: rule.proto, target_type: rule.target_type === "group" ? "group" : "single", ...(typeof rule.stream_name === "string" ? { title: rule.stream_name } : {}), ...(rule.proto.toUpperCase() === "RTP" && rule.fec === true ? { flowRoles: ["media", "fec_row", "fec_col"] } : {}) }];
    });
    return { targets, sourceText };
  }

  private schemaFile() { return path.resolve(path.dirname(this.stmConfigFile), "alerts_config.schema.json"); }
}

function parseJson(text: string, label: string): unknown {
  try { return JSON.parse(text) as unknown; }
  catch (error) { throw new AlertsValidationError("invalid " + label + ": " + String(error)); }
}

function parseObject(text: string, label: string): Record<string, unknown> {
  const value = parseJson(text, label);
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError("invalid " + label + ": must be an object");
  return value as Record<string, unknown>;
}

function validateRelativePath(value: unknown) {
  if (typeof value !== "string" || !value.trim()) throw new AlertsValidationError("alerts config path is required");
  const normalized = path.posix.normalize(value.trim());
  if (path.isAbsolute(normalized) || normalized === ".." || normalized.startsWith("../")) {
    throw new AlertsValidationError("alerts config path must remain under the STM config directory");
  }
  return normalized;
}

function validateDocument(value: unknown, metrics?: AlertMetricDefinition[], protocols?: string[]): AlertsDocument {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError("alerts config must be a monitoring-policy object");
  const record = value as Record<string, unknown>;
  ensureAllowed(record, new Set(["_note", "policies", "bindings"]), "alerts config");
  if (record._note !== undefined && typeof record._note !== "string") throw new AlertsValidationError("_note must be a string");
  if (!Array.isArray(record.policies) || !Array.isArray(record.bindings)) throw new AlertsValidationError("monitoring policy format requires policies and bindings arrays");
  const policies = record.policies.map((policy, index) => validatePolicy(policy, index, metrics, protocols));
  ensureUniqueIds(policies, "policy");
  const policyById = new Map(policies.map((policy) => [policy.id, policy]));
  const bindings = record.bindings.map((binding, index) => validateBinding(binding, index, policyById, metrics, protocols));
  const scopes = new Set<string>();
  for (const binding of bindings) {
    const key = bindingScopeKey(binding.scope);
    if (scopes.has(key)) throw new AlertsValidationError("bindings must not share a scope: " + key);
    scopes.add(key);
  }
  return { ...(typeof record._note === "string" ? { _note: record._note } : {}), policies, bindings };
}

function ensureAllowed(value: Record<string, unknown>, allowed: Set<string>, label: string) {
  for (const key of Object.keys(value)) if (!allowed.has(key)) throw new AlertsValidationError(label + ": unsupported field " + key);
}

function ensureUniqueIds(items: Array<{ id: string }>, label: string) {
  const ids = new Set<string>();
  for (const item of items) {
    if (ids.has(item.id)) throw new AlertsValidationError(label + " ids must be unique: " + item.id);
    ids.add(item.id);
  }
}

function validatePolicy(value: unknown, index: number, metrics?: AlertMetricDefinition[], protocols?: string[]): AlertPolicy {
  const prefix = "policy " + (index + 1);
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError(prefix + " must be an object");
  const policy = value as Record<string, unknown>;
  ensureAllowed(policy, new Set(["id", "title", "conditions"]), prefix);
  if (typeof policy.id !== "string" || !policy.id.trim()) throw new AlertsValidationError(prefix + ": id is required");
  if (policy.title !== undefined && typeof policy.title !== "string") throw new AlertsValidationError(prefix + ": title must be a string");
  if (!Array.isArray(policy.conditions)) throw new AlertsValidationError(prefix + ": conditions must be an array");
  const conditions = policy.conditions.map((condition, conditionIndex) => validateRule(condition, conditionIndex, metrics, protocols));
  ensureUniqueIds(conditions, prefix + " condition");
  return { id: policy.id, ...(typeof policy.title === "string" ? { title: policy.title } : {}), conditions };
}

function validateBinding(value: unknown, index: number, policies: Map<string, AlertPolicy>, metrics?: AlertMetricDefinition[], protocols?: string[]): AlertBinding {
  const prefix = "binding " + (index + 1);
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError(prefix + " must be an object");
  const binding = value as Record<string, unknown>;
  ensureAllowed(binding, new Set(["scope", "mode", "policy_id", "conditions", "adjustments", "additional_conditions"]), prefix);
  const scope = validateBindingScope(binding.scope, prefix, protocols);
  if (binding.mode !== "shared" && binding.mode !== "individual" && binding.mode !== "shared_with_adjustments" && binding.mode !== "disabled") throw new AlertsValidationError(prefix + ": mode is required");
  const mode = binding.mode;
  const policyId = typeof binding.policy_id === "string" && binding.policy_id.trim() ? binding.policy_id : undefined;
  const policy = policyId ? policies.get(policyId) : undefined;
  const hasConditions = binding.conditions !== undefined;
  const hasAdjustments = binding.adjustments !== undefined;
  const hasAdditional = binding.additional_conditions !== undefined;

  if (mode === "shared") {
    if (!policy) throw new AlertsValidationError(prefix + ": shared mode requires a known policy_id");
    if (hasConditions || hasAdjustments || hasAdditional) throw new AlertsValidationError(prefix + ": shared mode cannot include individual settings");
    return { scope, mode, policy_id: policyId };
  }
  if (mode === "individual") {
    if (policyId || hasAdjustments || hasAdditional) throw new AlertsValidationError(prefix + ": individual mode cannot include a shared policy or adjustments");
    if (!Array.isArray(binding.conditions) || binding.conditions.length === 0) throw new AlertsValidationError(prefix + ": individual mode requires non-empty conditions");
    const conditions = binding.conditions.map((condition, conditionIndex) => validateRule(condition, conditionIndex, metrics, protocols));
    ensureUniqueIds(conditions, prefix + " individual condition");
    return { scope, mode, conditions };
  }
  if (mode === "shared_with_adjustments") {
    if (!policy) throw new AlertsValidationError(prefix + ": shared_with_adjustments mode requires a known policy_id");
    if (hasConditions) throw new AlertsValidationError(prefix + ": shared_with_adjustments uses additional_conditions, not conditions");
    const conditionIds = new Set(policy.conditions.map((condition) => condition.id));
    let adjustments: Record<string, Partial<AlertRule>> | undefined;
    if (hasAdjustments) {
      if (!binding.adjustments || typeof binding.adjustments !== "object" || Array.isArray(binding.adjustments)) throw new AlertsValidationError(prefix + ": adjustments must be an object");
      adjustments = {};
      for (const [conditionId, adjustment] of Object.entries(binding.adjustments)) {
        if (!conditionIds.has(conditionId) || !adjustment || typeof adjustment !== "object" || Array.isArray(adjustment)) throw new AlertsValidationError(prefix + ": adjustment must refer to a policy condition");
        adjustments[conditionId] = validateAdjustment(adjustment as Record<string, unknown>, prefix + ": adjustment " + conditionId);
      }
    }
    let additionalConditions: AlertRule[] | undefined;
    if (hasAdditional) {
      if (!Array.isArray(binding.additional_conditions)) throw new AlertsValidationError(prefix + ": additional_conditions must be an array");
      additionalConditions = binding.additional_conditions.map((condition, conditionIndex) => validateRule(condition, conditionIndex, metrics, protocols));
      ensureUniqueIds(additionalConditions, prefix + " additional condition");
    }
    return { scope, mode, policy_id: policyId, ...(adjustments && Object.keys(adjustments).length ? { adjustments } : {}), ...(additionalConditions?.length ? { additional_conditions: additionalConditions } : {}) };
  }
  if (policyId || hasConditions || hasAdjustments || hasAdditional) throw new AlertsValidationError(prefix + ": disabled mode cannot include conditions or a policy");
  return { scope, mode: "disabled" };
}

function validateBindingScope(value: unknown, prefix: string, protocols?: string[]): AlertBindingScope {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError(prefix + ": scope is required");
  const scope = value as Record<string, unknown>;
  if (scope.kind === "protocol") {
    ensureAllowed(scope, new Set(["kind", "proto", "target"]), prefix + " protocol scope");
    if (scope.proto !== undefined && (typeof scope.proto !== "string" || (protocols && !protocols.includes(scope.proto)))) throw new AlertsValidationError(prefix + ": invalid protocol scope");
    if (scope.target !== undefined && !["any", "flow", "stream", "interface"].includes(String(scope.target))) throw new AlertsValidationError(prefix + ": invalid protocol target");
    return { kind: "protocol", ...(typeof scope.proto === "string" ? { proto: scope.proto } : {}), ...(scope.target !== undefined ? { target: scope.target as AlertTarget } : {}) };
  }
  if (scope.kind === "managed_target") {
    ensureAllowed(scope, new Set(["kind", "target_id", "target_type"]), prefix + " target scope");
    if (typeof scope.target_id !== "string" || !scope.target_id.trim()) throw new AlertsValidationError(prefix + ": managed target id is required");
    if (scope.target_type !== undefined && scope.target_type !== "single" && scope.target_type !== "group") throw new AlertsValidationError(prefix + ": invalid target type");
    return { kind: "managed_target", target_id: scope.target_id, ...(scope.target_type ? { target_type: scope.target_type as "single" | "group" } : {}) };
  }
  throw new AlertsValidationError(prefix + ": scope kind must be protocol or managed_target");
}

function bindingScopeKey(scope: AlertBindingScope) {
  return scope.kind === "protocol" ? "protocol:" + (scope.proto ?? "") + ":" + (scope.target ?? "any") : "managed_target:" + scope.target_id;
}

function validateAdjustment(value: Record<string, unknown>, prefix: string): Partial<AlertRule> {
  const permitted = new Set(["enabled", "severity", "error_threshold", "recover_threshold", "delta_threshold", "trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"]);
  ensureAllowed(value, permitted, prefix);
  for (const [key, candidate] of Object.entries(value)) {
    if (key === "enabled" && typeof candidate !== "boolean") throw new AlertsValidationError(prefix + ": enabled must be boolean");
    if (key === "severity" && (typeof candidate !== "string" || !candidate.trim())) throw new AlertsValidationError(prefix + ": severity must be a non-empty string");
    if (["error_threshold", "recover_threshold", "delta_threshold", "trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"].includes(key) && (typeof candidate !== "number" || !Number.isFinite(candidate) || (["trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"].includes(key) && candidate < 0))) throw new AlertsValidationError(prefix + ": " + key + " must be a non-negative finite number");
  }
  return value as Partial<AlertRule>;
}

function validateRule(value: unknown, index: number, metrics?: AlertMetricDefinition[], protocols?: string[]): AlertRule {
  const prefix = "row " + (index + 1);
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new AlertsValidationError(prefix + " must be an object");
  const rule = value as Record<string, unknown>;
  if (typeof rule.id !== "string" || !rule.id.trim()) throw new AlertsValidationError(prefix + ": id is required");
  if (typeof rule.metric !== "string" || !rule.metric.trim()) throw new AlertsValidationError(prefix + ": metric is required");
  if (rule.enabled !== undefined && typeof rule.enabled !== "boolean") throw new AlertsValidationError(prefix + ": enabled must be boolean");
  if (rule.target !== undefined && !["any", "flow", "stream", "interface"].includes(String(rule.target))) throw new AlertsValidationError(prefix + ": invalid target");
  if (rule.proto !== undefined && typeof rule.proto !== "string") throw new AlertsValidationError(prefix + ": proto must be a string");
  if (rule.flow_roles !== undefined) {
    if (rule.target !== "flow" || !Array.isArray(rule.flow_roles) || rule.flow_roles.length === 0 || rule.flow_roles.some((role) => typeof role !== "string" || !role.trim()) || new Set(rule.flow_roles).size !== rule.flow_roles.length) throw new AlertsValidationError(prefix + ": flow_roles must be a non-empty unique string list on flow rules");
    const flowRoles = rule.flow_roles as string[];
    const proto = typeof rule.proto === "string" ? rule.proto : undefined;
    if (proto && supportedFlowRoles[proto] && flowRoles.some((role) => !supportedFlowRoles[proto].includes(role))) throw new AlertsValidationError(prefix + ": flow_roles contains an unsupported role for " + proto);
  }
  if (rule.indicator_category !== undefined && rule.indicator_category !== "quality" && rule.indicator_category !== "other") throw new AlertsValidationError(prefix + ": indicator_category must be quality or other");
  if (typeof rule.proto === "string" && protocols && !protocols.includes(rule.proto)) throw new AlertsValidationError(prefix + ": protocol is not defined by the alerts schema");
  if (rule.type !== undefined && !["threshold", "counter_delta", "availability"].includes(String(rule.type))) throw new AlertsValidationError(prefix + ": invalid type");
  if (rule.operator !== undefined && ![">", ">=", "<", "<=", "==", "!="].includes(String(rule.operator))) throw new AlertsValidationError(prefix + ": invalid operator");
  if (metrics && !metrics.some((metric) => metric.key === rule.metric)) throw new AlertsValidationError(prefix + ": metric is not defined by the alerts schema");
  for (const key of ["error_threshold", "recover_threshold", "delta_threshold", "trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"] as const) {
    if (rule[key] !== undefined && (typeof rule[key] !== "number" || !Number.isFinite(rule[key]))) throw new AlertsValidationError(prefix + ": " + key + " must be a finite number");
  }
  for (const key of ["trigger_after_sec", "recover_after_sec", "missing_after_sec", "inactive_after_sec"] as const) if (rule[key] !== undefined && Number(rule[key]) < 0) throw new AlertsValidationError(prefix + ": " + key + " must be at least zero");
  if (rule.severity !== undefined && (typeof rule.severity !== "string" || !rule.severity.trim())) throw new AlertsValidationError(prefix + ": severity must be a non-empty string");
  const type = rule.type ?? "threshold";
  if (type === "threshold" && rule.error_threshold === undefined) throw new AlertsValidationError(prefix + ": error_threshold is required for threshold rules");
  if (type === "counter_delta" && rule.delta_threshold === undefined) throw new AlertsValidationError(prefix + ": delta_threshold is required for counter_delta rules");
  if (type === "availability" && (!(typeof rule.inactive_after_sec === "number") || rule.inactive_after_sec <= 0)) throw new AlertsValidationError(prefix + ": inactive_after_sec greater than zero is required for availability rules");
  return rule as AlertRule;
}

function parseSchema(value: unknown): { metrics: AlertMetricDefinition[]; protocols: string[] } {

import { readFile, writeFile } from "node:fs/promises";
import { existsSync } from "node:fs";
import type { FastifyInstance } from "fastify";
import type { StreamStore } from "../state/store";
import { config } from "../config";
import { MaintenanceSettings, SettingsConflictError, SettingsValidationError, type RuntimeSettings } from "../maintenanceSettings";
import { AlertsSettings, AlertsConflictError, AlertsValidationError } from "../alertsSettings";
import { ProtocolMapSettings, ProtocolMapConflictError, ProtocolMapValidationError } from "../protocolMapSettings";
import { CapturePolicySettings } from "../capturePolicySettings";
import { CaptureSettings, CaptureSettingsConflictError, CaptureSettingsValidationError } from "../captureSettings";
import { SetupSettings, SetupApplyError, SetupConflictError, SetupValidationError } from "../setupSettings";
import { SetupProfiles, SetupProfileError } from "../setupProfiles";
import { queryHistoricalSparklinesAt, queryInterfaceMetricsHistory, queryMetricsSnapshotAt, queryStreamMetricsHistory } from "../history/query";
import { queryTimelineHistory } from "../history/timeline_query";
import { AVAILABILITY_MAX_INTERVAL_SEC, queryLatestTimelineAvailabilityAtOrBefore, queryTimelineDataGaps } from "../history/timeline_availability_query";
import { queryEventsHistory, queryOverviewEventCounts } from "../history/events_query";
import { queryProjectedTopologyAt } from "../history/topology_state_query";
import { enrichProjectedStreamEventOverview, enrichProjectedStreamSnapshot, queryProjectedStreamsAt } from "../history/stream_state_query";
import type { DashboardLayout, InspectorLayout, InspectorTargetKind, TimelineRow, TimelineViewResponse } from "../types";
import type { CaptureHealthStore } from "../captureHealth";
import { ProcessControlClient, ProcessControlUnavailableError } from "../processControlClient";
import { RuntimeActivation, type RestartArea } from "../runtimeActivation";
import { managedProcessNames } from "../processControlProtocol";

export async function registerRoutes(
  app: FastifyInstance,
  store: StreamStore,
  maintenanceSettings: MaintenanceSettings,
  alertsSettings: AlertsSettings | undefined,
  protocolMapSettings: ProtocolMapSettings | undefined,
  capturePolicySettings: CapturePolicySettings,
  captureSettings: CaptureSettings | undefined,
  setupSettings: SetupSettings | undefined,
  setupProfiles: SetupProfiles,
  captureHealth: CaptureHealthStore,
  runtimeActivation: RuntimeActivation,
  processControl: ProcessControlClient,
  applyRuntimeSettings: (values: RuntimeSettings) => void
) {
  const historyTimings = new WeakMap<object, { metric: string; startedAt: number }>();

  app.addHook("onRequest", async (request) => {
    const metric = historyTimingMetric(request.raw.url);
    if (metric) historyTimings.set(request.raw, { metric, startedAt: performance.now() });
  });

  app.addHook("onSend", async (request, reply, payload) => {
    const timing = historyTimings.get(request.raw);
    if (timing) {
      const value = timing.metric + ";dur=" + (performance.now() - timing.startedAt).toFixed(1);
      const existing = reply.getHeader("Server-Timing");
      reply.header("Server-Timing", typeof existing === "string" ? existing + ", " + value : value);
    }
    reply.header("Cache-Control", "no-store");
    return payload;
  });

  app.get("/api/config", async () => ({
    lostRetentionSec: config.lostRetentionSec,
    historyWindowSec: config.historyWindowSec,
    staleAfterSec: config.staleAfterSec,
    diagnosticLog: config.diagnosticLog,
    dashboardLayoutEditMode: config.dashboardLayoutEditMode,
    streamsErrorCountMode: config.streamsErrorCountMode,
    streamsRecentAlertRetentionMin: config.streamsRecentAlertRetentionMin,
    streamsAlertDisplay: config.streamsAlertDisplay,
    historicalSparklines: config.historicalSparklines,
    streamsSparklineSamples: config.streamsSparklineSamples,
    tooltipDelayMs: config.tooltipDelayMs
  }));

  app.get("/api/live", async () => ({
    observedAt: await queryLatestTimelineAvailabilityAtOrBefore(Date.now() / 1000) ?? null
  }));

  app.get("/api/capture-health", async () => captureHealth.get());

  app.get("/api/runtime/processes", async () => runtimeView(runtimeActivation, processControl));

  app.post("/api/runtime/restarts/pending", async (_request, reply) => {
    const snapshot = await runtimeActivation.snapshot();
    const targets = runtimeActivation.pendingTargets(snapshot);
    if (!targets.length) return { operation: null, runtime: await runtimeView(runtimeActivation, processControl) };
    try {
      const operation = await processControl.restart(targets);
      await runtimeActivation.markRestarting(operation);
      return reply.code(202).send({ operation, runtime: await runtimeView(runtimeActivation, processControl) });
    } catch (error) {
      const message = error instanceof Error ? error.message : "process control is unavailable";
      return reply.code(error instanceof ProcessControlUnavailableError ? 503 : 409).send({ error: message });
    }
  });

  app.get<{ Params: { operationId: string } }>("/api/runtime/restarts/:operationId", async (request, reply) => {
    try {
      const operation = await processControl.operation(request.params.operationId);
      await runtimeActivation.reconcile(operation);
      return { operation, runtime: await runtimeView(runtimeActivation, processControl) };
    } catch (error) {
      const message = error instanceof Error ? error.message : "restart operation is unavailable";
      return reply.code(error instanceof ProcessControlUnavailableError ? 503 : 404).send({ error: message });
    }
  });

  app.get("/api/maintenance/capture-policy", async (_request, reply) => {
    try { return await capturePolicySettings.get(); }
    catch (error) { return reply.code(400).send({ error: error instanceof Error ? error.message : "failed to read capture policy" }); }
  });

  app.get("/api/maintenance/capture", async (_request, reply) => {
    if (!captureSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return await captureSettings.get(); }
    catch (error) { return reply.code(400).send({ error: error instanceof Error ? error.message : "failed to read capture config" }); }
  });

  app.put<{ Body: { revision?: unknown; document?: unknown } }>("/api/maintenance/capture", async (request, reply) => {
    if (!captureSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try {
      const before = await captureSettings.get();
      const updated = await captureSettings.update({ revision: request.body?.revision, document: request.body?.document });
      if (!sameJson(before.document, updated.document)) await runtimeActivation.markPending(["capture"]);
      return updated;
    }
    catch (error) {
      if (error instanceof CaptureSettingsConflictError) return reply.code(409).send({ error: error.message });
      if (error instanceof CaptureSettingsValidationError) return reply.code(400).send({ error: error.message });
      request.log.error({ error }, "failed to persist capture config");
      return reply.code(500).send({ error: "failed to persist capture config" });
    }
  });

  app.get("/api/setup/state", async (_request, reply) => {
    if (!setupSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return { ...await setupSettings.get(), runtime: await runtimeView(runtimeActivation, processControl) }; }
    catch (error) { return reply.code(400).send({ error: error instanceof Error ? error.message : "failed to load setup state" }); }
  });

  app.post<{ Body: unknown }>("/api/setup/preview", async (request, reply) => {
    if (!setupSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try { return await setupSettings.preview(request.body); }
    catch (error) {
      if (error instanceof SetupConflictError) return reply.code(409).send({ error: error.message });
      if (error instanceof SetupValidationError) return reply.code(400).send({ error: error.message });
      request.log.error({ error }, "failed to preview setup");
      return reply.code(500).send({ error: "failed to preview setup" });
    }
  });

  app.post<{ Body: unknown }>("/api/setup/apply", async (request, reply) => {
    if (!setupSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try {
      const result = await setupSettings.apply(request.body);
      await runtimeActivation.markPending(result.applied.filter(isRestartArea));
      const runtime = await runtimeView(runtimeActivation, processControl);
      return { ...result, state: { ...result.state, runtime }, runtime };
    }
    catch (error) {
      if (error instanceof SetupConflictError) return reply.code(409).send({ error: error.message });
      if (error instanceof SetupValidationError) return reply.code(400).send({ error: error.message });
      if (error instanceof SetupApplyError) return reply.code(500).send({ error: error.message, applied: error.applied });
      request.log.error({ error }, "failed to apply setup");
      return reply.code(500).send({ error: "failed to apply setup" });
    }
  });

  app.get("/api/setup/profiles", async () => ({ profiles: await setupProfiles.list() }));
  app.put<{ Body: { id?: unknown; name?: unknown; draft?: unknown } }>("/api/setup/profiles", async (request, reply) => {
    try { return await setupProfiles.save(request.body ?? {}); }
    catch (error) { return reply.code(400).send({ error: error instanceof Error ? error.message : "failed to save configuration profile" }); }
  });
  app.delete<{ Params: { id: string } }>("/api/setup/profiles/:id", async (request, reply) => {
    try { await setupProfiles.remove(request.params.id); return reply.code(204).send(); }
    catch (error) { return reply.code(error instanceof SetupProfileError ? 404 : 400).send({ error: error instanceof Error ? error.message : "failed to delete configuration profile" }); }
  });
  app.post<{ Params: { id: string } }>("/api/setup/profiles/:id/apply", async (request, reply) => {
    if (!setupSettings) return reply.code(503).send({ error: "STM config file is not configured for this server" });
    try {
      const [profile, state] = await Promise.all([setupProfiles.get(request.params.id), setupSettings.get()]);
