    const next = await this.read();
    const now = Date.now();
    const entries = Object.entries(next.processes) as Array<[ManagedProcessName, ActivationEntry]>;
    for (const [target, entry] of entries) {
      if (entry.operationId !== operation.id || entry.state !== "restarting") continue;
      const process = operation.processes.find((item) => item.name === target);
      const succeeded = operation.state === "succeeded" && process?.state === "RUNNING";
      const finished = operation.state !== "running";
      if (succeeded) next.processes[target] = { state: "current", areas: [], updatedAt: now };
