  const clock = uptime.match(/(\d+):(\d+):(\d+)/);
  if (!clock) return undefined;
  return (Number(days ?? 0) * 24 * 60 * 60) + (Number(clock[1]) * 60 * 60) + (Number(clock[2]) * 60) + Number(clock[3]);
}

function normalizeState(value: string): SupervisorProcessState {
  return ["RUNNING", "STARTING", "STOPPING", "STOPPED", "BACKOFF", "FATAL", "EXITED"].includes(value) ? value as SupervisorProcessState : "UNKNOWN";
}

async function removeSocket(socket: string) {
  try { await unlink(socket); }
  catch (error) { if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error; }
}

function optionsFromArgs(argv: string[]): Options {
  const value = (name: string) => { const index = argv.indexOf(name); return index >= 0 ? argv[index + 1] : undefined; };
  const socket = value("--socket");
  const supervisorConfig = value("--supervisor-config");
  if (!socket || !supervisorConfig) throw new Error("--socket and --supervisor-config are required");
  const socketGroup = value("--socket-group");
  if (socketGroup !== undefined && (!/^\d+$/.test(socketGroup) || Number(socketGroup) < 0)) throw new Error("--socket-group must be a numeric gid");
  return { socket, supervisorConfig, ...(socketGroup !== undefined ? { socketGroup: Number(socketGroup) } : {}), supervisorctl: value("--supervisorctl") ?? "supervisorctl" };
}

if (require.main === module) {
  const broker = new ProcessControlBroker(optionsFromArgs(process.argv.slice(2)));
  void broker.start().catch((error) => { console.error("process-control:", error); process.exitCode = 1; });
  process.on("SIGTERM", () => broker.stop());
  process.on("SIGINT", () => broker.stop());
}

