int main(int argc, char **argv) {
	cmdline::parser cp;
	cp.add<std::string>("config", 'c', "unified stm config JSON file", true, "");
	cp.add<std::string>("output", 'o', "capture health live NDJSON output", false, "");
	cp.add<std::uint32_t>("interval-sec", 0, "collection interval in seconds", false, 0);
	cp.add<std::string>("host-id", 0, "capture host identifier", false, "");
	cp.parse_check(argc, argv);

	capture_health::config cfg;
	std::string error;
	if(capture_health::load_config_file(cp.get<std::string>("config"), cfg, error) != 0) {
		std::fprintf(stderr, "stm_healthd: %s\n", error.c_str());
		return 1;
	}
	if(cp.exist("output")) cfg.output_file = cp.get<std::string>("output");
	if(cp.exist("interval-sec")) cfg.interval_sec = cp.get<std::uint32_t>("interval-sec");
	if(cp.exist("host-id")) cfg.host_id = cp.get<std::string>("host-id");
	if(!cfg.enabled) return 0;
	const auto output_file = cfg.output_file;
	const auto interval = cfg.interval_sec;

	std::signal(SIGINT, stop);
	std::signal(SIGTERM, stop);
	capture_health::collector collector(std::move(cfg));
	while(!stopping) {
		auto snapshot = collector.collect();
		if(!capture_health::write_live_file(output_file, snapshot, error)) std::fprintf(stderr, "stm_healthd: %s\n", error.c_str());
		if(!collector.write_transition_event(snapshot, error)) std::fprintf(stderr, "stm_healthd: %s\n", error.c_str());
		std::this_thread::sleep_for(std::chrono::seconds(interval));
	}
	return 0;
}
