std::string trim(std::string value) {
	const auto first = value.find_first_not_of(" \t\r\n");
	if(first == std::string::npos) return {};
	const auto last = value.find_last_not_of(" \t\r\n");
	return value.substr(first, last - first + 1);
}

bool read_text(const std::filesystem::path &path, std::string &out) {
	std::ifstream in(path);
	if(!in) return false;
	std::getline(in, out);
	out = trim(std::move(out));
	return !in.bad();
}

bool read_u64(const std::filesystem::path &path, std::uint64_t &out) {
	std::string text;
	if(!read_text(path, text) || text.empty()) return false;
	try {
		std::size_t consumed = 0;
		out = std::stoull(text, &consumed, 0);
		return consumed == text.size();
	}
	catch(...) {
		return false;
	}
}

bool read_i64(const std::filesystem::path &path, std::int64_t &out) {
	std::string text;
	if(!read_text(path, text) || text.empty()) return false;
	try {
		std::size_t consumed = 0;
		out = std::stoll(text, &consumed, 0);
		return consumed == text.size();
	}
	catch(...) {
		return false;
	}
}

json nullable_u64(const std::filesystem::path &path) {
	std::uint64_t value = 0;
	return read_u64(path, value) ? json(value) : json(nullptr);
}

std::vector<std::string> as_strings(const json &root, const char *key) {
	std::vector<std::string> result;
	if(!root.contains(key)) return result;
	const auto &value = root.at(key);
	if(value.is_string()) {
		std::stringstream stream(value.get<std::string>());
		std::string item;
		while(std::getline(stream, item, ',')) {
			item = trim(std::move(item));
			if(!item.empty()) result.push_back(std::move(item));
		}
	}
	else if(value.is_array()) {
		for(const auto &item : value) if(item.is_string() && !item.get<std::string>().empty()) result.push_back(item.get<std::string>());
	}
	return result;
}

std::filesystem::path resolve(const std::filesystem::path &base, const std::string &value) {
	const std::filesystem::path path(value);
	return path.is_absolute() ? path : base / path;
}

std::string fnv1a64(std::string_view value) {
	std::uint64_t hash = 14695981039346656037ULL;
	for(const unsigned char ch : value) {
		hash ^= ch;
		hash *= 1099511628211ULL;
	}
	std::ostringstream out;
	out << std::hex << std::setfill('0') << std::setw(16) << hash;
	return out.str();
}

std::string read_boot_id() {
	std::string value;
	return read_text("/proc/sys/kernel/random/boot_id", value) ? value : std::string{};
}

std::vector<std::string> discovered_interfaces() {
	std::vector<std::string> result;
	std::error_code error;
	for(const auto &entry : std::filesystem::directory_iterator("/sys/class/net", error)) {
		if(error) break;
		result.push_back(entry.path().filename().string());
	}
	std::sort(result.begin(), result.end());
	return result;
}

