volatile std::sig_atomic_t g_stop = 0;

void stop_handler(int) { g_stop = 1; }

double now_epoch() {
	return std::chrono::duration<double>(std::chrono::system_clock::now().time_since_epoch()).count();
}

std::vector<char*> to_exec_argv(std::vector<std::string> &argv) {
	std::vector<char*> out;
	out.reserve(argv.size() + 1);
	for(auto &arg : argv) {
		out.push_back(arg.data());
	}
	out.push_back(nullptr);
	return out;
}

bool write_status(const std::filesystem::path &path, const json &status) {
	if(path.empty()) return true;
	std::error_code error;
	std::filesystem::create_directories(path.parent_path(), error);
	if(error) return false;
	const auto temporary = path.string() + "." + std::to_string(getpid()) + ".tmp";
	{
		std::ofstream out(temporary, std::ios::trunc);
		if(!out) return false;
		out << status.dump() << '\n';
	}
	std::filesystem::rename(temporary, path, error);
	if(error) {
		std::filesystem::remove(temporary);
		return false;
	}
	return true;
}

int supervise(std::vector<std::string> argv, const dumpcap::resolved_config &resolved) {
	int stderr_pipe[2]{};
	if(pipe(stderr_pipe) != 0) {
		perror("pipe");
		return 1;
	}
	const auto pid = fork();
	if(pid < 0) {
		perror("fork");
		close(stderr_pipe[0]); close(stderr_pipe[1]);
		return 1;
	}
	if(pid == 0) {
		dup2(stderr_pipe[1], STDERR_FILENO);
		close(stderr_pipe[0]); close(stderr_pipe[1]);
		auto raw_args = to_exec_argv(argv);
		execvp(raw_args[0], raw_args.data());
		_exit(127);
	}
	close(stderr_pipe[1]);
	const int flags = fcntl(stderr_pipe[0], F_GETFL, 0);
	if(flags >= 0) (void)fcntl(stderr_pipe[0], F_SETFL, flags | O_NONBLOCK);
	std::signal(SIGINT, stop_handler);
	std::signal(SIGTERM, stop_handler);
	json status{{"schema_version", 1}, {"record_type", "capture_status"}, {"state", "running"}, {"pid", pid}, {"started_at", now_epoch()}, {"interfaces", resolved.interfaces}, {"buffer_size_mib_requested", resolved.cfg.buffer_size_mib}, {"statistics_requested", false}, {"filter_configured", !resolved.cfg.bpf_filter.empty()}, {"ring_duration_sec", resolved.cfg.ring_duration_sec}, {"ring_files", resolved.cfg.ring_files}, {"drop_count", nullptr}};
	if(!resolved.cfg.system_policy_revision.empty()) status["system_policy_revision"] = resolved.cfg.system_policy_revision;
	(void)write_status(resolved.cfg.status_file, status);
	std::string pending;
	int child_status = 0;
	bool child_exited = false;
	while(!child_exited) {
		if(g_stop) kill(pid, SIGTERM);
		pollfd fd{.fd = stderr_pipe[0], .events = POLLIN, .revents = 0};
		(void)poll(&fd, 1, 1000);
		char buffer[4096]{};
		const auto count = read(stderr_pipe[0], buffer, sizeof(buffer));
		if(count > 0) {
			(void)write(STDERR_FILENO, buffer, static_cast<std::size_t>(count));
			pending.append(buffer, static_cast<std::size_t>(count));
			const auto newline = pending.rfind('\n');
			if(newline != std::string::npos) {
				status["last_message"] = pending.substr(0, newline);
				if(status["last_message"].get<std::string>().size() > 1024) status["last_message"] = status["last_message"].get<std::string>().substr(status["last_message"].get<std::string>().size() - 1024);
				pending.erase(0, newline + 1);
			}
		}
		status["observed_at"] = now_epoch();
		(void)write_status(resolved.cfg.status_file, status);
		const auto waited = waitpid(pid, &child_status, WNOHANG);
		child_exited = waited == pid || (waited < 0 && errno == ECHILD);
	}
	close(stderr_pipe[0]);
	status["state"] = "exited";
	status["ended_at"] = now_epoch();
	if(WIFEXITED(child_status)) status["exit_code"] = WEXITSTATUS(child_status);
	else if(WIFSIGNALED(child_status)) status["signal"] = WTERMSIG(child_status);
	(void)write_status(resolved.cfg.status_file, status);
	return WIFEXITED(child_status) ? WEXITSTATUS(child_status) : 1;
}

