  private readonly server = net.createServer((socket) => this.handle(socket));

  constructor(private readonly options: Options) {}

  async start() {
    await removeSocket(this.options.socket);
    await new Promise<void>((resolve, reject) => {
      this.server.once("error", reject);
      this.server.listen(this.options.socket, () => { this.server.off("error", reject); resolve(); });
    });
    await chmod(this.options.socket, 0o660);
    if (this.options.socketGroup !== undefined) await chown(this.options.socket, 0, this.options.socketGroup);
  }

  stop() {
    this.server.close(() => process.exit(0));
  }

  private handle(socket: net.Socket) {
    let input = "";
    socket.setEncoding("utf8");
    socket.on("data", (chunk: string) => {
      input += chunk;
      if (input.length > maxRequestBytes) return socket.end(JSON.stringify({ ok: false, error: "request too large" }) + "\n");
      const newline = input.indexOf("\n");
      if (newline < 0) return;
      const line = input.slice(0, newline);
      void this.dispatch(line).then((value) => socket.end(JSON.stringify({ ok: true, ...value }) + "\n"), (error: unknown) => socket.end(JSON.stringify({ ok: false, error: error instanceof Error ? error.message : "process control failed" }) + "\n"));
    });
    socket.on("error", () => undefined);
  }

  private async dispatch(line: string): Promise<Record<string, unknown>> {
    let request: Record<string, unknown>;
    try { request = JSON.parse(line) as Record<string, unknown>; }
    catch { throw new Error("invalid request"); }
    if (request.action === "status") return { processes: await this.status() };
    if (request.action === "operation" && typeof request.id === "string") {
      const operation = this.operations.get(request.id);
      if (!operation) throw new Error("restart operation was not found");
      return { operation };
    }
    if (request.action === "restart" && Array.isArray(request.targets)) {
      const targets = [...new Set(request.targets)];
      if (!targets.length || !targets.every(isManagedProcessName)) throw new Error("restart targets are invalid");
      if ([...this.operations.values()].some((item) => item.state === "running")) throw new Error("a restart operation is already running");
      return { operation: this.restart(targets) };
    }
    throw new Error("unsupported process control action");
  }

  private restart(targets: ManagedProcessName[]): RestartOperation {
    const operation: RestartOperation = { id: randomUUID(), state: "running", targets, processes: [], startedAt: Date.now() };
    this.operations.set(operation.id, operation);
    void this.runRestart(operation);
    return operation;
  }

  private async runRestart(operation: RestartOperation) {
    try {
      for (const target of operation.targets) await this.supervisorctl(["restart", target], 90_000);
      const statuses = await this.status();
      operation.processes = statuses.filter((item) => operation.targets.includes(item.name));
      if (operation.processes.every((item) => item.state === "RUNNING")) operation.state = "succeeded";
      else {
        operation.state = "failed";
        operation.error = "one or more services did not reach RUNNING";
      }
    } catch (error) {
      operation.state = "failed";
      operation.error = error instanceof Error ? error.message : "restart failed";
      try { operation.processes = (await this.status()).filter((item) => operation.targets.includes(item.name)); } catch { /* Preserve the original failure. */ }
    }
    operation.completedAt = Date.now();
  }

  private async status(): Promise<ProcessInfo[]> {
    const { stdout } = await this.supervisorctl(["status", ...managedProcessNames], 5_000);
    const parsed = new Map(parseSupervisorStatus(stdout).map((item) => [item.name, item]));
    return managedProcessNames.map((name) => parsed.get(name) ?? { name, state: "UNKNOWN", detail: "not reported by supervisor" });
  }

  private supervisorctl(args: string[], timeout: number) {
    return execFileAsync(this.options.supervisorctl, ["-c", this.options.supervisorConfig, ...args], { timeout, maxBuffer: 1024 * 1024 });
  }
}

function parseSupervisorStatus(value: string): ProcessInfo[] {
  return value.split("\n").flatMap((line): ProcessInfo[] => {
    const match = line.match(/^([^\s]+)\s+([^\s]+)(?:\s+(.*))?$/);
    if (!match || !isManagedProcessName(match[1])) return [];
    const state = normalizeState(match[2]);
    const detail = match[3]?.trim();
    const pid = detail?.match(/\bpid\s+(\d+)/i)?.[1];
    const uptimeSeconds = supervisorUptimeSeconds(detail);
    return [{ name: match[1], state, ...(pid ? { pid: Number(pid) } : {}), ...(uptimeSeconds !== undefined ? { startedAt: Date.now() - uptimeSeconds * 1000 } : {}), ...(detail ? { detail } : {}) }];
  });
}

function supervisorUptimeSeconds(detail: string | undefined) {
  const uptime = detail?.match(/\buptime\s+(.+)$/i)?.[1];
  if (!uptime) return undefined;
  const days = uptime.match(/(\d+)\s+day(?:s)?/i)?.[1];
  const clock = uptime.match(/(\d+):(\d+):(\d+)/);
  if (!clock) return undefined;
  return (Number(days ?? 0) * 24 * 60 * 60) + (Number(clock[1]) * 60 * 60) + (Number(clock[2]) * 60) + Number(clock[3]);
}

function normalizeState(value: string): SupervisorProcessState {
  return ["RUNNING", "STARTING", "STOPPING", "STOPPED", "BACKOFF", "FATAL", "EXITED"].includes(value) ? value as SupervisorProcessState : "UNKNOWN";
}

async function removeSocket(socket: string) {
  try { await unlink(socket); }
  catch (error) { if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error; }
}

function optionsFromArgs(argv: string[]): Options {
  const value = (name: string) => { const index = argv.indexOf(name); return index >= 0 ? argv[index + 1] : undefined; };
  const socket = value("--socket");
  const supervisorConfig = value("--supervisor-config");
  if (!socket || !supervisorConfig) throw new Error("--socket and --supervisor-config are required");
  const socketGroup = value("--socket-group");
  if (socketGroup !== undefined && (!/^\d+$/.test(socketGroup) || Number(socketGroup) < 0)) throw new Error("--socket-group must be a numeric gid");
  return { socket, supervisorConfig, ...(socketGroup !== undefined ? { socketGroup: Number(socketGroup) } : {}), supervisorctl: value("--supervisorctl") ?? "supervisorctl" };
}

if (require.main === module) {
  const broker = new ProcessControlBroker(optionsFromArgs(process.argv.slice(2)));
  void broker.start().catch((error) => { console.error("process-control:", error); process.exitCode = 1; });
  process.on("SIGTERM", () => broker.stop());
  process.on("SIGINT", () => broker.stop());
}
